Get Payment Log > OpenAPI definition #/components/schemas/CbuaePaymentLogPaymentResponse

{
 "description": "The payment response as received from the financial institution as a result of a `make-payment` call, as it stands after every patch the LFI has applied to it.\n`paymentRail` selects the shape, exactly as it does on `patch /payment-log/{id}`: the rail determines which status the payment can be in, whether it carries a `paymentTransactionId`, and which reject reason code namespace applies. A payment the LFI has not yet routed carries no `paymentRail` at all — see `CbuaePaymentLogPaymentResponseUnrouted`.\n`CbuaePatchPaymentRecordBody` describes what each rail means and the obligations that travel with it.\n",
 "oneOf": [
 {
 "$ref": "#/components/schemas/CbuaePaymentLogPaymentResponseAani"
 },
 {
 "$ref": "#/components/schemas/CbuaePaymentLogPaymentResponseFts"
 },
 {
 "$ref": "#/components/schemas/CbuaePaymentLogPaymentResponseLfi"
 },
 {
 "$ref": "#/components/schemas/CbuaePaymentLogPaymentResponseUnrouted"
 }
 ]
}

Get Payment Log > OpenAPI definition #/components/schemas/CbuaePaymentLogPaymentResponseAani

{
 "description": "A payment the LFI routed to AANI, the UAE instant payment platform.\n",
 "type": "object",
 "required": [
 "paymentRail",
 "status"
 ],
 "additionalProperties": false,
 "properties": {
 "id": {
 "description": "A unique id for the payment in uuid-v4 format.\n",
 "type": "string"
 },
 "paymentRail": {
 "description": "Identifies AANI as the rail the payment was routed to.\n",
 "type": "string",
 "enum": [
 "AANI"
 ],
 "example": "AANI"
 },
 "status": {
 "description": "The current status of the payment.\n* `AcceptedSettlementCompleted`: **not terminal.** The LFI has passed the payment to AANI and is awaiting\n confirmation.\n\n* `AcceptedWithoutPosting`: terminal. AANI has confirmed the payment.\n* `Rejected`: terminal. The payment will not be settled, and `rejectReasonCode` carries the reason.\n",
 "type": "string",
 "enum": [
 "AcceptedSettlementCompleted",
 "AcceptedWithoutPosting",
 "Rejected"
 ]
 },
 "paymentTransactionId": {
 "description": "The AANI-generated end to end transaction identifier, as issued to the Originating LFI. This is not the same value as the `transactionId` in the Bank Data Sharing API. It is absent where the payment was rejected before AANI issued an identifier.\n",
 "type": "string",
 "minLength": 1,
 "maxLength": 40
 },
 "creationDateTime": {
 "allOf": [
 {
 "$ref": "#/components/schemas/AEDateTime"
 },
 {
 "description": "An ISO date-time representing when the payment was created"
 }
 ]
 },
 "statusUpdateDateTime": {
 "allOf": [
 {
 "$ref": "#/components/schemas/AEDateTime"
 },
 {
 "description": "An ISO date-time representing when the payment status was last updated"
 }
 ]
 },
 "OpenFinanceBilling": {
 "$ref": "#/components/schemas/AEServiceInitiationOpenFinancePaymentBilling"
 },
 "rejectReasonCode": {
 "$ref": "#/components/schemas/CbuaePaymentLogRejectReasonCodeAani"
 }
 }
}

