Get Payment Log > OpenAPI definition #/components/schemas/CbuaePaymentLogPaymentResponseUnrouted

{
 "description": "A payment the LFI has not routed to a rail. `paymentRail` is absent, because no rail has been selected yet or none ever was: the payment is either still pending at the LFI, or was rejected before the LFI submitted it anywhere.\nA payment in this state has not been patched with a rail. Once the LFI patches `paymentResponse.paymentRail` the record takes the shape of that rail instead.\n",
 "type": "object",
 "required": [
 "status"
 ],
 "additionalProperties": false,
 "properties": {
 "id": {
 "description": "A unique id for the payment in uuid-v4 format.\n",
 "type": "string"
 },
 "status": {
 "description": "The current status of the payment.\n* `Pending`: the LFI has the payment and has not yet routed it to a rail. Further checks and a status\n update will follow.\n\n* `Rejected`: terminal. The LFI rejected the payment before selecting a rail, and `rejectReasonCode`\n carries the reason.\n",
 "type": "string",
 "enum": [
 "Pending",
 "Rejected"
 ]
 },
 "creationDateTime": {
 "allOf": [
 {
 "$ref": "#/components/schemas/AEDateTime"
 },
 {
 "description": "An ISO date-time representing when the payment was created"
 }
 ]
 },
 "statusUpdateDateTime": {
 "allOf": [
 {
 "$ref": "#/components/schemas/AEDateTime"
 },
 {
 "description": "An ISO date-time representing when the payment status was last updated"
 }
 ]
 },
 "OpenFinanceBilling": {
 "$ref": "#/components/schemas/AEServiceInitiationOpenFinancePaymentBilling"
 },
 "rejectReasonCode": {
 "$ref": "#/components/schemas/CbuaePaymentLogRejectReasonCode"
 }
 }
}

